#[test]
fn generated_header_identifies_compiler_and_uses_prelude() {
    let generated =
        vest::compile("header.vest", "value = u8".to_string()).expect("compile a minimal format");

    assert!(generated.starts_with(&format!(
        "// Auto-generated by vest v{}.\n\
         // Do not edit manually; edit the .vest source and regenerate instead.\n\n",
        env!("CARGO_PKG_VERSION")
    )));
    assert!(generated.contains("use vest_lib::prelude::*;"));
    assert!(!generated.contains("use vstd::prelude::*;"));
    assert!(!generated.contains("use vest_lib::combinators::*;"));
}
